/* Fleet page-foot restart: tap the build readout, restart the app, see how it ended.
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app.
 * The server half is the vendored `src/self_restart.py` (`GET`/`POST
 * /api/restart`); the app declares its restart targets there, in code. No
 * targets, or no route, and the readout stays plain text.
 *
 * The page waits for `/api/version` to report a new process (`built_at` is
 * captured at process start, so it changes on every restart even when the
 * SHA does not) and for the server's record of the run. An unknown result is
 * never shown as success: each ending has its own outcome below.
 */

import { buildReadoutText } from './page-foot.js';

export const POLL_INTERVAL_MS = 1500;
export const RESTART_TIMEOUT_MS = 90 * 1000;

const FAILED_STATES = ['failed', 'timeout', 'error', 'unknown'];

// The outcome of one restart so far. `before` and `live` are /api/version
// bodies (`live` is null while the app is down), `last` is the server's
// restart record. Returns 'pending', 'restarted', 'unconfirmed', 'failed' or
// 'timed-out'.
export function outcome(before, live, last, restartId, elapsedMs, timeoutMs) {
  const mine = last && last.id === restartId ? last : null;
  if (mine && FAILED_STATES.includes(mine.state)) return 'failed';
  const newProcess = Boolean(before && before.built_at && live && live.built_at &&
    live.built_at !== before.built_at);
  if (newProcess && mine && mine.state === 'ok') return 'restarted';
  if (elapsedMs < timeoutMs) return 'pending';
  return (newProcess || (mine && mine.state === 'ok')) ? 'unconfirmed' : 'timed-out';
}

async function defaultFetchJson(url) {
  const res = await fetch(url, { cache: 'no-store', credentials: 'same-origin' });
  if (!res.ok) {
    const err = new Error('HTTP ' + res.status);
    err.status = res.status;
    throw err;
  }
  return res.json();
}

async function defaultPostJson(url, body) {
  const res = await fetch(url, {
    method: 'POST',
    cache: 'no-store',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  let data = null;
  try { data = await res.json(); } catch (_) { data = null; }
  return { status: res.status, body: data };
}

function closeIcon() {
  return '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" fill="none" ' +
    'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
    '<path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>';
}

function buildSheet(targets) {
  const dialog = document.createElement('dialog');
  dialog.className = 'detail-dialog restart-sheet';
  dialog.dataset.trackView = 'build.restart';
  // The id the app's UX surface map lists; stamped here because the app has
  // no markup of its own for this sheet.
  dialog.dataset.surface = 'app.restart-sheet';

  const card = document.createElement('div');
  card.className = 'detail-card';
  const header = document.createElement('div');
  header.className = 'detail-header';
  const title = document.createElement('h2');
  title.textContent = 'Restart';
  title.setAttribute('tabindex', '-1');
  title.setAttribute('autofocus', '');
  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'icon-button detail-close';
  close.dataset.track = 'build.restart-close';
  close.setAttribute('aria-label', 'Close');
  close.innerHTML = closeIcon();
  header.append(title, close);
  card.append(header);

  let picker = null;
  if (targets.length > 1) {
    picker = document.createElement('select');
    picker.className = 'select-native';
    picker.dataset.track = 'build.restart-target';
    picker.setAttribute('aria-label', 'What to restart');
    for (const target of targets) {
      const option = document.createElement('option');
      option.value = target.id;
      option.textContent = target.label;
      picker.append(option);
    }
    card.append(picker);
  }

  const note = document.createElement('p');
  note.className = 'restart-sheet-note';
  note.setAttribute('aria-live', 'polite');
  const log = document.createElement('pre');
  log.className = 'restart-sheet-log';
  log.hidden = true;

  const actions = document.createElement('div');
  actions.className = 'detail-actions';
  const confirm = document.createElement('button');
  confirm.type = 'button';
  confirm.className = 'button-primary detail-save-btn';
  confirm.dataset.track = 'build.restart-confirm';
  actions.append(confirm);
  card.append(note, log, actions);
  dialog.append(card);
  return { dialog, close, picker, note, log, confirm };
}

function failureText(last) {
  if (last && last.state === 'unknown') return 'Restart result unknown: the runner stopped reporting.';
  if (last && last.state === 'timeout') return 'Restart failed: the recipe did not finish in time.';
  const code = last && last.exit_code != null ? ' (exit ' + last.exit_code + ')' : '';
  return 'Restart failed' + code + '.';
}

function liveLine(live) {
  return buildReadoutText(live.git_sha || 'unknown', live.built_at || '');
}

// Starts one restart and waits for its outcome; `ui.finish(text, tone, lines)`
// ends a run that leaves the sheet open, `ui.done(text)` one that reloads.
async function runRestart(deps, ui, target) {
  let before = null;
  try { before = await deps.fetchJson(deps.versionEndpoint); } catch (_) { before = null; }
  let started;
  try {
    started = await deps.postJson(deps.endpoint, { target: target.id });
  } catch (_) {
    ui.finish('Could not reach the app to start the restart.', 'error');
    return;
  }
  if (started.status === 401 || started.status === 403) {
    ui.finish('Not allowed from here: sign in to this app first.', 'error');
    return;
  }
  if (started.status === 409) {
    ui.finish('A restart is already running.', 'error');
    return;
  }
  if (started.status !== 202 || !started.body || !started.body.restart_id) {
    ui.finish('Could not start the restart (HTTP ' + started.status + ').', 'error');
    return;
  }
  const restartId = started.body.restart_id;
  const t0 = deps.now();
  for (;;) {
    await deps.sleep(POLL_INTERVAL_MS);
    let live = null;
    let last = null;
    try { live = await deps.fetchJson(deps.versionEndpoint); } catch (_) { live = null; }
    try { last = (await deps.fetchJson(deps.endpoint)).last; } catch (_) { last = null; }
    const result = outcome(before, live, last, restartId, deps.now() - t0, deps.timeoutMs);
    if (result === 'pending') continue;
    if (result === 'restarted') {
      ui.done('Restarted · ' + liveLine(live));
    } else if (result === 'failed') {
      ui.finish(failureText(last), 'error', last && last.log_tail);
    } else if (result === 'unconfirmed') {
      ui.finish('The app is back, but the restart result is not confirmed.' +
        (live ? ' ' + liveLine(live) : ''), 'warning');
    } else {
      ui.finish('The app did not come back in ' + Math.round(deps.timeoutMs / 1000) +
        ' s. Restart it from the PC with tray.bat --restart.', 'error');
    }
    return;
  }
}

function makeTappable(readout, open) {
  readout.classList.add('page-foot-restart');
  readout.setAttribute('role', 'button');
  readout.setAttribute('tabindex', '0');
  readout.setAttribute('aria-haspopup', 'dialog');
  readout.setAttribute('data-track', 'build.restart-open');
  readout.addEventListener('click', open);
  readout.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      open();
    }
  });
}

// Re-reads the target list into `targets` (and the picker's option text) so a
// warning that depends on live state is the one true now. A failed read keeps
// the list the page already has.
async function refreshTargets(deps, targets, picker) {
  let fresh = null;
  try { fresh = (await deps.fetchJson(deps.endpoint)).targets; } catch (_) { fresh = null; }
  if (!Array.isArray(fresh)) return;
  for (const next of fresh) {
    const known = targets.find((t) => t.id === next.id);
    if (known) {
      known.label = next.label;
      known.warning = next.warning;
    }
  }
  if (!picker) return;
  for (const option of picker.children) {
    const known = targets.find((t) => t.id === option.value);
    if (known) option.textContent = known.label;
  }
}

// The sheet's state and handlers; returns the function that opens it.
function wireSheet(sheet, targets, deps, reload) {
  let armed = false;
  let busy = false;
  let refreshing = false;
  const chosen = () => {
    const id = sheet.picker ? sheet.picker.value : targets[0].id;
    return targets.find((t) => t.id === id) || targets[0];
  };
  const say = (text, tone) => {
    sheet.note.textContent = text;
    if (tone) sheet.note.dataset.tone = tone;
    else delete sheet.note.dataset.tone;
  };
  const showLog = (lines) => {
    sheet.log.textContent = (lines || []).join('\n');
    sheet.log.hidden = !(lines && lines.length);
  };
  const setLocked = (locked, label) => {
    sheet.confirm.disabled = locked;
    sheet.confirm.textContent = label;
    if (sheet.picker) sheet.picker.disabled = locked;
  };
  const reset = () => {
    armed = false;
    setLocked(false, chosen().label);
    say('The app stops for a few seconds and comes back on its current code.');
    showLog([]);
  };
  const ui = {
    finish(text, tone, lines) {
      busy = false;
      armed = false;
      say(text, tone);
      showLog(lines);
      setLocked(false, 'Try again');
    },
    done(text) {
      busy = false;
      say(text);
      reload();
    },
  };

  sheet.confirm.addEventListener('click', () => {
    if (busy || refreshing) return;
    const target = chosen();
    if (target.warning && !armed) {
      armed = true;
      say(target.warning, 'warning');
      sheet.confirm.textContent = 'Restart anyway';
      return;
    }
    busy = true;
    setLocked(true, target.label);
    showLog([]);
    say('Restarting…');
    runRestart(deps, ui, target);
  });
  if (sheet.picker) sheet.picker.addEventListener('change', () => { if (!busy && !refreshing) reset(); });
  sheet.close.addEventListener('click', () => sheet.dialog.close());
  // The confirm button is held until the read lands, so a tap can never act on
  // the warning the page loaded with. Resolves once the sheet is ready.
  return async () => {
    if (busy) {
      sheet.dialog.showModal();
      return;
    }
    reset();
    sheet.dialog.showModal();
    if (refreshing) return;
    refreshing = true;
    setLocked(true, chosen().label);
    try {
      await refreshTargets(deps, targets, sheet.picker);
    } finally {
      refreshing = false;
    }
    if (!busy) reset();
  };
}

// Wires the restart onto the build readout. Resolves to true when the app
// offers a restart, false when it does not (no route, no targets, a refused
// read), in which case the readout is left untouched.
export async function initRestartSheet(opts) {
  const o = opts || {};
  const readout = o.readout || document.getElementById('buildReadout');
  const deps = {
    fetchJson: o.fetchJson || defaultFetchJson,
    postJson: o.postJson || defaultPostJson,
    endpoint: o.endpoint || '/api/restart',
    versionEndpoint: o.versionEndpoint || '/api/version',
    sleep: o.sleep || ((ms) => new Promise((resolve) => setTimeout(resolve, ms))),
    now: o.now || (() => Date.now()),
    timeoutMs: o.timeoutMs || RESTART_TIMEOUT_MS,
  };
  const reload = o.reload || (() => location.reload());

  if (!readout) return false;
  let targets;
  try {
    targets = (await deps.fetchJson(deps.endpoint)).targets || [];
  } catch (_) {
    return false;
  }
  if (!targets.length) return false;

  const sheet = buildSheet(targets);
  document.body.appendChild(sheet.dialog);
  makeTappable(readout, wireSheet(sheet, targets, deps, reload));
  return true;
}
